`timescale 1fs/1fs
//======================================================================
// ams_node_pkg -- the analog node type.
//
// AUTO-GENERATED by spice2rnm (Veylon Systems).  Edits will be overwritten.
//
// A SPICE node is bidirectional: current is injected into it and a voltage
// is present on it, and both belong to the same net. A `real` port carries
// one direction, which is why a model with `real` ports must split every
// node in two -- and why such a model cannot be instantiated against the
// netlist's own hierarchy. This type carries both, so a port can BE a node.
//
// RESOLUTION. Currents SUM: that is Kirchhoff, and the reason several
// drivers on one net is meaningful at all. Voltage does not sum -- exactly
// one element establishes it (a filter's state, a supply, a driven source)
// and the rest read it. A driver says which it is with `drives_v`.
//
// Two voltage owners on one net is a MODELLING ERROR, not something to
// average: it means two elements each believe they set the same node. It is
// reported rather than silently resolved, because picking one produces a
// circuit that runs and is wrong.
//======================================================================
package ams_node_pkg;

  typedef struct {
    real i;         // amps INTO the node, summed across drivers
    real v;         // volts on the node, from its one owner
    bit  drives_v;  // this driver establishes the voltage
  } ams_node_t;

  function automatic ams_node_t ams_node_res(input ams_node_t drivers[]);
    ams_node_t r;
    int owners;
    r.i = 0.0;
    r.v = 0.0;
    r.drives_v = 1'b0;
    owners = 0;
    foreach (drivers[k]) begin
      r.i += drivers[k].i;
      if (drivers[k].drives_v) begin
        r.v = drivers[k].v;
        r.drives_v = 1'b1;
        owners++;
      end
    end
    if (owners > 1)
      $error("%m: %0d voltage owners on one node; exactly one element may establish a node's voltage. Summing currents is Kirchhoff; averaging voltages is not.", owners);
    return r;
  endfunction

  nettype ams_node_t ams_node with ams_node_res;

  function automatic ams_node_t drive_i(input real amps);
    drive_i = '{i: amps, v: 0.0, drives_v: 1'b0};
  endfunction

  function automatic ams_node_t drive_v(input real volts);
    drive_v = '{i: 0.0, v: volts, drives_v: 1'b1};
  endfunction

endpackage : ams_node_pkg
